/usr/bin/bash -lc "python - <<'PY'
import csv,json,re
with open('market.csv',newline='') as f: rows=list(csv.DictReader(f))
active=[r for r in rows if r['is_resolved'].lower()=='false' and r['resolution_date']<='2026-06-18']
arts=[]
with open('articles/2026/06/09/articles.jsonl') as f:
 for line in f:
  try:a=json.loads(line)
  except:continue
  if str(a.get('date_publish') or '')[:10]=='2026-06-09':arts.append(a)
for r in active:
 pred=json.loads(r['my_prediction']);hits=[]
 for name in pred:
  if len(name)<5:continue
  pat=re.compile(r'(?<"'!'"\\\\w)'+re.escape(name)+r'(?"'!'"\\\\w)',re.I)
  ms=[a for a in arts if pat.search((a.get('title') or '')+' '+(a.get('content') or ''))]
  if ms:hits.append((name,len(ms),[a.get('title') or '' for a in ms[:3]]))
 if hits:
  print(f\"\\n{r['qid']} | {r['resolution_date']} | {r['title']}\")
  for name,n,titles in hits:print(f\"  {name}: {n} :: {' || '.join(titles)}\")
PY"

